insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-141', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'Increasing s-character in a hybrid orbital of carbon', '["lengthens the bond and lowers its enthalpy","shortens the bond and raises bond enthalpy","leaves bond length unchanged","converts every sigma bond into a pi bond"]'::jsonb, 1, 'An sp carbon (50% s) holds electrons closer than sp3 (25% s), so C-H and C-C bonds become shorter and stronger.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
