insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-142', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'The observed H-N-H angle in ammonia is about 107° rather than 109.5° because', '["nitrogen remains completely unhybridised","the lone pair occupies more space than a bond pair and compresses the angles","the molecule is trigonal planar","hydrogen bonding forces NH3 to become linear"]'::jsonb, 1, 'lp-bp repulsion > bp-bp repulsion, so the three N-H bonds are squeezed slightly below the tetrahedral value.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
