insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-144', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'According to Fajan’s rules, a cation polarises an anion more strongly if the cation is', '["large and of low charge","small and of high charge","isoelectronic with neon and nothing else","colourless in aqueous solution"]'::jsonb, 1, 'High charge density on a small, highly charged cation distorts the anion’s electron cloud.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
